//! Feature generator trait definition
//!
//! Defines the core trait that all feature generators must implement.

use crate::config::{LagConfig, RollingConfig, TrendConfig};
use crate::error::Result;

/// SQL column expression generated by a feature
#[derive(Debug, Clone, PartialEq)]
pub struct SqlColumn {
    /// SQL expression (e.g., "LAG(pm25_mean, 1) OVER (...)")
    pub expression: String,
    /// Column alias (e.g., "pm25_mean_lag_1h")
    pub alias: String,
    /// PostgreSQL data type (e.g., "DOUBLE PRECISION")
    pub data_type: String,
}

impl SqlColumn {
    /// Create a new SQL column
    pub fn new(
        expression: impl Into<String>,
        alias: impl Into<String>,
        data_type: impl Into<String>,
    ) -> Self {
        Self {
            expression: expression.into(),
            alias: alias.into(),
            data_type: data_type.into(),
        }
    }

    /// Format as SQL with alias
    pub fn to_sql(&self) -> String {
        format!("{} AS {}", self.expression, self.alias)
    }
}

/// Feature configuration (type-erased wrapper)
#[derive(Debug, Clone, Default)]
pub struct FeatureConfig {
    /// Lag hours for lag features
    pub lags_hours: Vec<u32>,
    /// Windows for rolling/trend features
    pub windows: Vec<String>,
    /// Statistics for rolling features
    pub stats: Vec<String>,
    /// Single window for trend features
    pub trend_window: Option<String>,
}

impl FeatureConfig {
    /// Create from LagConfig
    pub fn from_lag(lag: &LagConfig) -> Self {
        Self {
            lags_hours: lag.lags_hours.clone(),
            ..Default::default()
        }
    }

    /// Create from RollingConfig
    pub fn from_rolling(rolling: &RollingConfig) -> Self {
        Self {
            windows: rolling.windows.clone(),
            stats: rolling.stats.clone(),
            ..Default::default()
        }
    }

    /// Create from TrendConfig
    pub fn from_trend(trend: &TrendConfig) -> Self {
        Self {
            trend_window: Some(trend.window.clone()),
            ..Default::default()
        }
    }
}

/// Trait for feature generators
///
/// Implement this trait to add new feature computation types.
/// Each implementation generates SQL column expressions for a specific
/// type of time-series feature.
pub trait FeatureGenerator: Send + Sync {
    /// Unique identifier for this feature type (e.g., "lag", "rolling", "trend")
    fn feature_type(&self) -> &str;

    /// Generate SQL column expressions for this feature
    ///
    /// # Arguments
    /// * `config` - Feature-specific configuration
    /// * `field` - The field name to generate features for
    ///
    /// # Returns
    /// Vector of SQL column expressions
    fn generate_columns(&self, config: &FeatureConfig, field: &str) -> Result<Vec<SqlColumn>>;

    /// Validate the feature configuration
    fn validate(&self, config: &FeatureConfig) -> Result<()>;

    /// Whether this feature requires window functions
    fn requires_window(&self) -> bool;

    /// Human-readable description of this feature type
    fn description(&self) -> &str;
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_sql_column_new() {
        let col = SqlColumn::new(
            "AVG(pm25) OVER (...)",
            "pm25_rolling_mean_4h",
            "DOUBLE PRECISION",
        );

        assert_eq!(col.expression, "AVG(pm25) OVER (...)");
        assert_eq!(col.alias, "pm25_rolling_mean_4h");
        assert_eq!(col.data_type, "DOUBLE PRECISION");
    }

    #[test]
    fn test_sql_column_to_sql() {
        let col = SqlColumn::new(
            "LAG(pm25_mean, 1) OVER (PARTITION BY ndp_id ORDER BY bucket)",
            "pm25_mean_lag_1h",
            "DOUBLE PRECISION",
        );

        let sql = col.to_sql();
        assert!(sql.contains(" AS pm25_mean_lag_1h"));
    }

    #[test]
    fn test_feature_config_from_lag() {
        let lag = LagConfig {
            enabled: true,
            lags_hours: vec![1, 6, 24],
            fields: vec!["pm25_mean".to_string()],
        };

        let config = FeatureConfig::from_lag(&lag);

        assert_eq!(config.lags_hours, vec![1, 6, 24]);
        assert!(config.windows.is_empty());
    }

    #[test]
    fn test_feature_config_from_rolling() {
        let rolling = RollingConfig {
            enabled: true,
            windows: vec!["4 hours".to_string()],
            stats: vec!["mean".to_string(), "std".to_string()],
            fields: vec!["pm25_mean".to_string()],
        };

        let config = FeatureConfig::from_rolling(&rolling);

        assert_eq!(config.windows, vec!["4 hours"]);
        assert_eq!(config.stats, vec!["mean", "std"]);
    }
}
